#!/bin/sh
# Hiscore restore/save path on Enduro Racer: the saved table (the index 4
# NVRAM file) is streamed in through the 16-bit ioctl path, the game boots and
# fills its table from ROM, hiscore.v puts the saved one back, then an OSD
# open and an index 4 upload read the same bytes back. Both checks must print
# PASS. Enduro Racer is the set whose hiscore.dat lines all match from the
# first frames (Hang-On's and Space Harrier's flag word only reads 01 some
# 20 s into the attract, which would make a bench run of this gate long).
# Both fixtures are written here (verif/golden/ is not in git):
#   hs_cfg.bin  = tools/gen_mra.py hiscore_config("enduror")
#   hs_dump.bin = the game's own default table (work RAM at frame 300 in
#                 MAME) with every letter shifted by three
set -e
cd "$(dirname "$0")/../.."
PY=verif/.venv/bin/python
ZIP="/Volumes/roms/Arcade/MAME 0.289 ROMs (merged)/enduror.zip"
G=verif/golden/enduror
mkdir -p $G
[ -f $G/main.hex ] || $PY tools/pack_roms.py enduror --zip "$ZIP" --out /dev/null --hexdir $G
python3 - <<'PYEOF'
import sys; sys.path.insert(0, "tools"); import gen_mra, romsets
open("verif/golden/enduror/hs_cfg.bin", "wb").write(gen_mra.hiscore_config(romsets.ROMSETS["enduror"]))
open("verif/golden/enduror/hs_dump.bin", "wb").write(bytes.fromhex(
    ""))
PYEOF
pkill -f Vtb_board 2>/dev/null || true
make -C verif/board build >/dev/null
make -C verif/board run GAME=enduror FRAMES=${FRAMES:-70} PLUSARGS="+hiscore=$PWD/$G +hs_check=${HS_CHECK:-60}" 2>&1 | tee verif/board/out/hiscore.log | grep -E "HISCORE|ABORT|WATCHDOG" || true
grep -q "restore check.*PASS" verif/board/out/hiscore.log && grep -q "upload check.*PASS" verif/board/out/hiscore.log && echo "hiscore: PASS" || { echo "hiscore: FAIL"; exit 1; }
